package store

import (
	"context"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
	"github.com/aws/aws-sdk-go-v2/service/ssm"
	"github.com/aws/aws-sdk-go-v2/service/s3"
)

func Get(ctx context.Context, c *dynamodb.Client, name string) {
	table := "default-table"
	if name != "" {
		table = name
	}
	c.GetItem(ctx, &dynamodb.GetItemInput{TableName: aws.String(table)})
}

