package store

import (
	"context"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
	"github.com/aws/aws-sdk-go-v2/service/ssm"
	"github.com/aws/aws-sdk-go-v2/service/s3"
)

func getParam(ctx context.Context, c *ssm.Client, name string) {
	c.GetParameter(ctx, &ssm.GetParameterInput{Name: aws.String(name)})
}

func FeatureFlag(ctx context.Context, c *ssm.Client, flag string) bool {
	getParam(ctx, c, "/app/flags")
	return flag != ""
}

